const cloneSeed=()=>JSON.parse(JSON.stringify(seed));const readDemoStorage=(key,fallback,valid)=>{try{const raw=localStorage.getItem(key);if(!raw)return fallback;const value=JSON.parse(raw);return valid(value)?value:fallback}catch{return fallback}};const persistDemoStorage=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};let state=readDemoStorage('eventpilot-demo',cloneSeed(),v=>v&&Array.isArray(v.incidents)&&Array.isArray(v.approvals)&&Array.isArray(v.audits)&&Array.isArray(v.messages));const save=()=>{persistDemoStorage('eventpilot-demo',state);if(apiMode&&serverUser?.role==='manager'){clearTimeout(opsSaveTimer);opsSaveTimer=setTimeout(()=>apiCall('/api/ops-state','POST',{event_id:activeEventId,state}).catch(err=>toast('Could not save event operations: '+err.message,true)),250)}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const $=s=>document.querySelector(s);const $$=s=>document.querySelectorAll(s);const icons={mentor:'♧',deadline:'◷',stream:'⌁',other:'✳'};const names={overview:'Overview',operations:'AI Operations',communications:'Communication Hub',participants:'Participants & teams',schedule:'Schedule & resources','keynote-resources':'Keynote resources',mentors:'Mentor management',reports:'Reports & audit',participant:'My Dashboard',events:'Your events','participant-events':'My events',checkin:'Check in',venue:'Venue map',keynote:'Keynote & notes','tech-details':'Technical details',submission:'Submission portal',support:'Mentor & technical support',community:'Community & socials',notifications:'Notifications',results:'Results & feedback'};
