async function apiCall(path,method='GET',payload){const options={method,credentials:'same-origin',headers:{}};if(payload!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(payload)}const response=await fetch(path,options);let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data}
async function loadServerEvents(){const data=await apiCall('/api/events');eventList=data.events;persistDemoStorage('eventpilot-events',eventList);renderEvents()}
async function loadOperations(eventId){activeEventId=eventId;try{const data=await apiCall(`/api/ops-state?event_id=${encodeURIComponent(eventId)}`);if(data.state)state=data.state;else{state=eventId==='EV-01'?cloneSeed():{incidents:[],approvals:[],audits:[],messages:[],completed:0};await apiCall('/api/ops-state','POST',{event_id:eventId,state})}save()}catch(err){toast(`Could not load this event’s operations: ${err.message}`,true)}}
