async function signIn(role,email,password,eventCode=''){if(apiMode){try{const result=await apiCall('/api/login','POST',{role,email,password,event_code:eventCode});serverUser=result.user;if(role==='manager'){activeEventId='EV-01';await loadServerEvents();await loadOperations(activeEventId)}else{activeEventId=result.event_id;await loadServerEvents();await loadParticipantSummary()}enterApp(role);return}catch(err){toast(err.message,true);return}}enterApp(role)}
async function startServerModel(){if(location.protocol==='file:')return;try{await apiCall('/api/health');apiMode=true;const session=await apiCall('/api/me');if(session.authenticated){serverUser=session.user;if(serverUser.role==='manager'){await loadServerEvents();activeEventId='EV-01';await loadOperations(activeEventId)}else{await loadServerEvents();activeEventId=session.event_id;await loadParticipantSummary()}enterApp(serverUser.role)}}catch{apiMode=false}}
