function getProfile(role){const name=role==="participant"?(serverUser?.name||"Jordan Patel"):"Alex Morgan";const email=role==="participant"?(serverUser?.email||"jordan@eventbase.demo"):"alex@eventbase.demo";return readDemoStorage("eventbase-profile-"+role,{name,email,eventUpdates:true,productNews:false},v=>v&&typeof v.name==="string"&&typeof v.email==="string")}
function renderProfile(role){const profile=getProfile(role),initials=profile.name.trim().split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase()||"AM";document.querySelector(".user-profile b").textContent=profile.name;document.querySelector(".avatar").textContent=initials;document.querySelector(".top-avatar").textContent=initials;$("#profile-menu-initials").textContent=initials;$("#profile-menu-name").textContent=profile.name;$("#profile-menu-role").textContent=role==="participant"?"Participant":"Event manager"}
