async function openEvent(id){let item=eventList.find(x=>x.id===id);if(!item)return;activeEventId=item.id;activeEventName=item.name;document.querySelector(".event-icon").textContent=item.name.slice(0,1).toUpperCase();document.querySelector(".banner-copy b").textContent=item.name;$('.event-name b').textContent=item.name;$('.event-name small').textContent=`${item.type} · ${formatDate(item.date)}`;$('.breadcrumbs span:first-child').textContent=item.name;if(apiMode&&serverUser?.role==='manager')await loadOperations(item.id);go('overview');toast(`${item.name} workspace opened.`)}async function startManagerDemo(){state=cloneSeed();eventList=JSON.parse(JSON.stringify(baseEvents));activeEventId='EV-01';activeEventName='Hack the Future 2025';persistDemoStorage('eventpilot-demo',state);persistDemoStorage('eventpilot-events',eventList);showRole('manager');await signIn('manager','manager@eventbase.demo','eventbase-demo');if(!document.body.classList.contains('authenticated')||document.body.classList.contains('participant-mode'))return;const event=eventList.find(x=>x.id==='EV-01')||eventList[0];if(event)openEvent(event.id)}function openCreate(){ $('#create-event-modal').classList.add('open') }function closeCreate(){ $('#create-event-modal').classList.remove('open') }
