function renderReports(){let resolved=state.incidents.filter(i=>i.status==='resolved').length;$('#report-incidents').textContent=4+state.incidents.filter(i=>!['INC-204','INC-203'].includes(i.id)).length;$('#report-approved').textContent=3+state.audits.filter(a=>a.type==='approval'&&a.title.includes('Approved')).length;$('#report-messages').textContent=state.messages.length;$('#outcome-list').innerHTML=[['✓','Mentor rescheduling','2 teams matched · approval before reassigning',resolved?'Verified':'In progress'],['▱','Participant communications',`${state.messages.length} simulated messages · no external delivery`,'Simulated'],['◷','Submission readiness','8 incomplete teams identified · complete teams excluded','Tracked']].map(x=>`<div class="outcome-row"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div><span class="outcome-state">${x[3]}</span></div>`).join('');let filter=$('#audit-filter')?.value||'all';let aud=state.audits.filter(a=>filter==='all'||a.type===filter);$('#audit-list').innerHTML=aud.map(a=>`<div class="audit-row"><span class="audit-icon">${a.type==='approval'?'✓':a.type==='system'?'⌘':'✳'}</span><div><b>${esc(a.title)}</b><p>${esc(a.description)}</p><small>${a.actor|| (a.type==='approval'?'Alex Morgan':'EventBase AI')} · Recorded in demo workspace</small></div><time>${a.time}</time></div>`).join('')}
